insert into public.datapoints_taxonomia
  (codigo, marco, norma, pilar, seccion_indice, estandar, edicion, nombre, pilar_asg, como_se_mide, descripcion, pagina_origen, version_taxonomia)
values
  ('IBSO A.1', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Emisiones GEI: alcance 1', 'A', 'tCO₂e. Datos de actividad × factores de emisión, considerando los gases correspondientes.', 'Emisiones directas de fuentes propias o controladas: combustibles en vehículos, calderas, plantas de emergencia y fugas de refrigerantes. Recopilar consumos, recargas y factores utilizados.', null, '2025'),
  ('IBSO A.2', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Emisiones GEI: alcance 2', 'A', 'tCO₂e asociadas con la energía adquirida y consumida.', 'Emisiones indirectas por electricidad, calor, vapor o enfriamiento comprados. Recopilar recibos, consumos y factores de emisión aplicables.', null, '2025'),
  ('IBSO A.3', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Emisiones GEI: alcance 3', 'A', 'tCO₂e, identificando las categorías de la cadena de valor incluidas y los métodos de estimación.', 'Otras emisiones indirectas: compras, transporte, viajes, residuos, uso de productos e inversiones, según las actividades de la entidad. Documentar cobertura, supuestos y fuentes.', null, '2025'),
  ('IBSO A.4', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Consumo energético', 'A', 'Energía total consumida, convirtiendo combustibles y electricidad a una unidad energética común.', 'Cuánta energía utiliza la entidad. Recopilar electricidad, combustibles y otras fuentes; evitar duplicar energía transformada internamente.', null, '2025'),
  ('IBSO A.5', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Energía renovable consumida', 'A', 'Energía renovable en unidad energética; como referencia, renovable ÷ consumo total × 100.', 'Qué parte del consumo procede de fuentes renovables. Distinguir generación propia y energía adquirida, con evidencia de su origen.', null, '2025'),
  ('IBSO A.6', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Inversión sostenible', 'A', 'Importe monetario de las inversiones que cumplen los criterios aplicables y su medida relativa conforme a la norma.', 'Recursos destinados a actividades sostenibles. Identificar inversiones, criterios de clasificación y respaldo contable; no asumir que todo gasto ambiental califica.', null, '2025'),
  ('IBSO A.7', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Agua ingresada', 'A', 'Volumen de agua que entra a la entidad, generalmente en m³.', 'Agua obtenida de la red, pozos, cuerpos superficiales u otras fuentes. Recopilar medidores, facturas, permisos y estimaciones documentadas.', null, '2025'),
  ('IBSO A.8', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Agua reaprovechada', 'A', 'Volumen reutilizado o reciclado, en m³, y su proporción con la base definida por la norma.', 'Agua utilizada nuevamente en procesos u operaciones. Identificar circuitos de reúso y mediciones para evitar duplicidades.', null, '2025'),
  ('IBSO A.9', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Aguas residuales descargadas', 'A', 'Volumen descargado en m³.', 'Agua residual que sale de las operaciones. Identificar volúmenes y destinos: alcantarillado, cuerpos receptores u otros.', null, '2025'),
  ('IBSO A.10', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Aguas residuales tratadas', 'A', 'Volumen tratado y descargado en m³; proporción respecto de las descargas correspondientes.', 'Qué parte de las aguas residuales descargadas recibió tratamiento. Recopilar registros de plantas propias o servicios externos.', null, '2025'),
  ('IBSO A.11', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Agua de zonas con estrés hídrico', 'A', 'm³ ingresados de esas zonas y porcentaje respecto del agua total ingresada.', 'Dependencia de fuentes ubicadas en zonas con estrés hídrico. Vincular los volúmenes con su ubicación y con una evaluación geográfica documentada.', null, '2025'),
  ('IBSO A.12', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Suelo en zonas sensibles para la biodiversidad o próximas a ellas', 'A', 'Superficie en m² o hectáreas, con conversión uniforme, y proporción correspondiente.', 'Superficie utilizada dentro o cerca de áreas de riesgo para la biodiversidad. Recopilar coordenadas, polígonos, superficies y cartografía ambiental.', null, '2025'),
  ('IBSO A.13', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Dependencia de sustancias que agotan el ozono', 'A', 'Cantidades de sustancias, convertidas a equivalentes de CFC-11 mediante su potencial de agotamiento del ozono.', 'Uso de sustancias que dañan la capa de ozono. Revisar inventarios químicos, refrigerantes y fichas técnicas; distinguirlas de otros gases de efecto invernadero.', null, '2025'),
  ('IBSO A.14', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Residuos generados', 'A', 'Masa total de residuos, normalmente en toneladas.', 'Cuántos residuos produce la entidad. Consolidar pesajes, bitácoras, manifiestos y registros de gestores.', null, '2025'),
  ('IBSO A.15', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Residuos reaprovechados', 'A', 'Toneladas recuperadas para reaprovechamiento; como referencia, reaprovechados ÷ generados × 100.', 'Residuos destinados a reutilización, reciclaje u otras formas de aprovechamiento. Conservar evidencia del destino efectivo.', null, '2025'),
  ('IBSO A.16', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Residuos peligrosos', 'A', 'Toneladas de residuos clasificados como peligrosos y su medida relativa aplicable.', 'Generación de residuos con características de peligrosidad. Respaldar la clasificación y los volúmenes con registros y manifiestos.', null, '2025'),
  ('IBSO B.1', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Gestión de igualdad y trabajo digno', 'S', 'Cualitativo: existencia y aplicación de políticas y prácticas.', 'Cómo se promueven igualdad de oportunidades, no discriminación y condiciones de trabajo dignas. Recopilar políticas, procedimientos y evidencia de implementación.', null, '2025'),
  ('IBSO B.2', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Brecha salarial', 'S', 'Comparación de remuneraciones entre mujeres y hombres por categoría ocupacional; diferencia monetaria y relativa según la metodología normativa.', 'Diferencias de remuneración entre grupos comparables. Recopilar nómina, categorías y componentes salariales bajo criterios consistentes.', null, '2025'),
  ('IBSO B.3', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Capacitación', 'S', 'Horas de capacitación y promedio por trabajador, con los desgloses aplicables.', 'Tiempo dedicado a formación del personal. Recopilar cursos, duración, participantes y plantilla utilizada para calcular los promedios.', null, '2025'),
  ('IBSO B.4', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Evaluación y desarrollo profesional', 'S', 'Número de trabajadores evaluados y porcentaje de cobertura sobre la población correspondiente.', 'Alcance de las evaluaciones de desempeño y desarrollo. Recopilar evaluaciones realizadas, universo elegible y registros de seguimiento.', null, '2025'),
  ('IBSO B.5', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Gestión de salud y seguridad laboral', 'S', 'Cualitativo: políticas, procedimientos y mecanismos de prevención y seguimiento.', 'Cómo se administran los riesgos para la salud y seguridad del personal. Recopilar programas, responsables, capacitación e inspecciones.', null, '2025'),
  ('IBSO B.6', 'NIS', 'S1'::public.norma_niif, 'metricas'::public.pilar_niif, null, 'NIS A-1', '2024', 'Accidentes y enfermedades laborales con incapacidad o fallecimiento', 'S', 'Conteos de casos y medidas relativas con el denominador que establece la norma.', 'Accidentes y enfermedades de trabajo que provocaron incapacidad o muerte. Recopilar registros laborales y médicos, separando los tipos de consecuencia.', null, '2025'),
  ('IBSO C.1', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Consejo de administración', 'G', 'Cualitativo: existencia y características del órgano de administración.', 'Estructura de gobierno de la entidad. Recopilar actas constitutivas, integración del consejo, funciones y reglas de operación.', null, '2025'),
  ('IBSO C.2', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Participación de mujeres en el consejo', 'G', 'Número de consejeras y mujeres ÷ integrantes totales × 100.', 'Representación femenina en el consejo. Utilizar una integración y fecha de corte consistentes.', null, '2025'),
  ('IBSO C.3', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Vigilancia independiente', 'G', 'Cualitativo: existencia, funciones e independencia del órgano correspondiente.', 'Mecanismos independientes de vigilancia. Recopilar nombramientos, atribuciones y elementos que respalden su independencia.', null, '2025'),
  ('IBSO C.4', 'NIS', 'S1'::public.norma_niif, 'riesgos'::public.pilar_niif, null, 'NIS A-1', '2024', 'Política de riesgos', 'G', 'Cualitativo: existencia y aplicación de una política de administración de riesgos.', 'Cómo se identifican, evalúan, atienden y supervisan los riesgos. Recopilar política, metodología, responsables y registros de seguimiento.', null, '2025'),
  ('IBSO C.5', 'NIS', 'S1'::public.norma_niif, 'estrategia'::public.pilar_niif, null, 'NIS A-1', '2024', 'Estrategia de sostenibilidad', 'G', 'Cualitativo: existencia y contenido de la estrategia.', 'Cómo se integra la sostenibilidad en la gestión empresarial. Recopilar estrategia aprobada, objetivos, acciones, responsables y seguimiento.', null, '2025'),
  ('IBSO C.6', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Integridad y ética', 'G', 'Cualitativo: existencia y aplicación del código y sus mecanismos de cumplimiento.', 'Reglas de conducta y cómo se implementan. Recopilar código, aprobaciones, comunicación, capacitación y mecanismos de denuncia y atención.', null, '2025'),
  ('IBSO C.7', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Seguridad de información', 'G', 'Cualitativo: políticas y mecanismos para proteger la información.', 'Gestión de riesgos que afectan confidencialidad, integridad y disponibilidad. Recopilar políticas, controles de acceso y procedimientos ante incidentes.', null, '2025'),
  ('IBSO C.8', 'NIS', 'S1'::public.norma_niif, 'gobernanza'::public.pilar_niif, null, 'NIS A-1', '2024', 'Privacidad y protección de datos de terceros', 'G', 'Cualitativo: políticas y procedimientos de protección de datos.', 'Cómo se resguardan los datos de clientes, proveedores y otros terceros. Recopilar avisos de privacidad, autorizaciones y controles de tratamiento y conservación.', null, '2025')
